      "en": "Be careful when you put on these boots, as there might still be a foot or two of the previous owner inside them.",
      "es": "Ten cuidado al ponerte estas botas, puede que lleven dentro uno o dos pies de su dueño anterior.",
      "fr": "Attention en enfilant ces bottes, il n'est pas rare qu'elles contiennent encore un ou deux pieds du propriétaire précédent.",
