    "description": {
      "id": "37162",
      "de": "Diese Waffe ist das Symbol der weißen Ratten. Sie steht in dem Ruf, Freund wie Feind gleichermaßen problemlos durchbohren zu können.",
      "en": "This weapon is the symbol of the White Rat. It will slice both enemies and allies with the same ease.",
      "es": "Esta arma es el símbolo de la Rata Blanca. Es famosa por ser capaz de cortar tanto a enemigos como a aliados con la misma facilidad.",
      "fr": "Cette Arme est le symbole du Rat Blanc. Elle est réputée pour être capable de trancher ennemis et alliés avec la même facilité.",
      "pt": "Esta arma é o símbolo do Rato Branco. Sabe-se que sua capacidade de cortar em fatias tanto inimigos como aliados com facilidade é a mesma."
    },
